  - [Humidity, sensor.demo_humidity, "{{ 'DRY' if states('sensor.demo_humidity') | float < 40 else 'OK' }}"]
  - [Battery, sensor.demo_battery, "{{ states('sensor.demo_battery') | int }}%"]
